insert into constitution.capabilities(capability_code,name,description,risk_tier,execution_mode,required_approval_stage,input_schema,output_schema,metadata,created_at,updated_at)
select 'CAP-ESL-006','Decision Intelligence and Explainability Engine','Converts governed strategy evaluations into ranked decision options, calibrated confidence, explicit tradeoffs, sensitivity findings, and auditable explanations.','critical','approval_required','founder',jsonb_build_object('required',jsonb_build_array('experiment_id','decision_question')),jsonb_build_object('produces',jsonb_build_array('recommendation','option_assessments','explanation_factors','sensitivity_findings','audit_record')),jsonb_build_object('constitutional_rules',jsonb_build_array('never fabricate evidence','never hide material uncertainty','never suppress dissenting findings','never recommend an ineligible strategy','never execute an external action','human approval required before consequential use')),now(),now()
where not exists(select 1 from constitution.capabilities where capability_code='CAP-ESL-006');